class _Cell:
    def __init__(self):
        self._dependents = []

    def _add_dependent(self, cell):
        self._dependents.append(cell)


class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        _propagate(self)


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = inputs
        self._compute_function = compute_function
        self._callbacks = []
        for cell in inputs:
            cell._add_dependent(self)
        self._value = self._compute_function([cell.value for cell in inputs])

    @property
    def value(self):
        return self._value

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

    def _recompute(self):
        new_value = self._compute_function([cell.value for cell in self._inputs])
        if new_value != self._value:
            self._value = new_value
            for callback in self._callbacks:
                callback(new_value)


def _propagate(changed_input):
    # Collect every compute cell that transitively depends on the input.
    cells = []
    seen = set()
    stack = list(changed_input._dependents)
    while stack:
        cell = stack.pop()
        if id(cell) in seen:
            continue
        seen.add(id(cell))
        cells.append(cell)
        stack.extend(cell._dependents)

    # Recompute in topological order: a cell is ready once none of its
    # inputs are still pending. Each cell is recomputed exactly once, so
    # callbacks fire once with the final stable value.
    remaining = set(cells)
    while remaining:
        for cell in list(remaining):
            if all(id(dep) not in remaining for dep in cell._inputs):
                remaining.remove(cell)
                cell._recompute()

